choose.otherwise:
and (


        or exists (
            select 1 from identity_user ou
            join tenant_member om on om.user_id = ou.id and om.tenant_id = a.tenant_id
            join tenant_member_org omo on omo.member_id = om.id and omo.tenant_id = om.tenant_id
            where om.status = 1 and om.left_at is null
              and omo.org_id in

                  #{scopeOrgId}

              and (ou.username = t.ASSIGNEE_ or concat('', ou.id) = t.ASSIGNEE_)
        )


        or t.ASSIGNEE_ in

            #{scopeSelfIdentifier}



        or (t.ASSIGNEE_ is null and exists (
            select 1 from ACT_HI_IDENTITYLINK sk
            where sk.TASK_ID_ = t.ID_
              and sk.TYPE_ = 'candidate'
              and (


                      or sk.USER_ID_ in

                          #{scopeCandidateIdentifier}



                      or sk.GROUP_ID_ in

                          #{scopeCandidateGroup}



              )
        ))


)

mapper.sql:
where a.tenant_id = #{c.tenantId}
  and a.business_type 

    and a.process_definition_key in

        #{processDefinitionKey}



    and a.business_key in

        #{businessKey}



    and a.id not in

        #{deniedApplyId}



    and t.TASK_DEF_KEY_ in

        #{taskDefinitionKey}



    and (
        t.ASSIGNEE_ in

            #{assigneeIdentifier}


            or exists (
                select 1 from identity_user iu
                join tenant_member tm on tm.user_id = iu.id and tm.tenant_id = a.tenant_id
                where iu.id in

                    #{assigneeId}

                and iu.username = t.ASSIGNEE_
            )

    )


    and ()


    and coalesce(a.applicant_dept_id, a.org_id) in

        #{deptId}





        and t.ASSIGNEE_ is not null
        and t.ASSIGNEE_ is null



    and a.apply_status in

        #{applyStatus}





            and exists (
                select 1 from workflow_task_record r
                where r.tenant_id = a.tenant_id
                  and r.process_instance_id = a.process_instance_id
                  and r.action = 'RETURN'
            )


            and not exists (
                select 1 from workflow_task_record r
                where r.tenant_id = a.tenant_id
                  and r.process_instance_id = a.process_instance_id
                  and r.action = 'RETURN'
            )




    and t.START_TIME_ >= #{c.createTimeBegin}


    and t.START_TIME_ <= #{c.createTimeEnd}


    and t.END_TIME_ >= #{c.endTimeBegin}


    and t.END_TIME_ <= #{c.endTimeEnd}



        and a.id in (
        select fa.apply_id
        from workflow_business_apply_attribute fa
        where fa.tenant_id = #{c.tenantId}
          and fa.business_type 
          and fa.attr_key = #{condition.key}
          and fa.attr_value in

            #{value}

        )



    and a.created_time >= #{c.applyTimeBegin}


    and a.created_time <= #{c.applyTimeEnd}


    and (t.NAME_ like #{c.keyword} or t.TASK_DEF_KEY_ like #{c.keyword})


    and (a.apply_code like #{c.applyKeyword}
         or a.apply_title like #{c.applyKeyword}
         or a.apply_summary like #{c.applyKeyword})


    and (
        t.ASSIGNEE_ in

            #{selfIdentifier}

        or exists (
            select 1 from ACT_HI_IDENTITYLINK il
            where il.TASK_ID_ = t.ID_
              and il.TYPE_ = 'candidate'
              and (
                  il.USER_ID_ in

                      #{selfIdentifier}


                      or il.GROUP_ID_ in

                          #{selfGroup}


              )
        )
    )

mapper.select:
select links.TASK_ID_ as taskId, links.USER_ID_ as userId, links.GROUP_ID_ as groupId from ( select TASK_ID_, USER_ID_, GROUP_ID_ from ACT_HI_IDENTITYLINK where TYPE_ = 'candidate' and TASK_ID_ in
#{taskId}
union select TASK_ID_, USER_ID_, GROUP_ID_ from ACT_RU_IDENTITYLINK where TYPE_ = 'candidate' and TASK_ID_ in
#{taskId}
) links

select iu.username
from identity_user iu
join tenant_member tm on tm.user_id = iu.id and tm.tenant_id = #{tenantId}
where iu.id in

    #{userId}
